from devtools.resources.commands import CommandOutputPolicy
from dataclasses import FrozenInstanceError
for name in ("max_stdout_bytes","max_stderr_bytes","max_pending_events"):
    for value in (True,False,1.5,"5",None):
        try: CommandOutputPolicy(**{name:value})
        except ValueError: pass
        except Exception as error: raise AssertionError((name,value,type(error).__name__)) from error
        else: raise AssertionError((name,value,"non-integer admitted"))
for count in (0,1,1024):
    p=CommandOutputPolicy(max_stdout_bytes=count,max_stderr_bytes=count,max_pending_events=max(1,count))
    assert p.max_stdout_bytes==count
for name,value in (("max_stdout_bytes",-1),("max_stderr_bytes",-1),("max_pending_events",0)):
    try: CommandOutputPolicy(**{name:value})
    except ValueError: pass
    else: raise AssertionError("invalid integer bound admitted")
try: CommandOutputPolicy().max_stdout_bytes=5
except FrozenInstanceError: pass
else: raise AssertionError("mutable policy")
print("22 independent policy scenarios passed")
